// Digital twin for Drive.H — TI DRV2605 haptic driver for LRA/ERM actuators.
// (DRV2605, not the DRV2605L: it has an integrated boost converter fed from a
// separate drive supply, which is why the tile carries two rails — V+ VDD logic
// and V_MOTOR boost/drive.) Output-centric: firmware selects a mode +
// waveform/amplitude and the chip drives a differential haptic output
// (OUT+/OUT-, boostable above V_MOTOR). This twin models the drive envelope
// (0..1 strength) on the OUT pads plus the status/diagnostic/voltage reads,
// with register-accurate conversions from the DRV2605 datasheet.
//
// Controls drive the same state a firmware program would set (RTP amplitude,
// play/stop, supply, faults), so the actuator output can be exercised here.
import type { TileSim } from '../tileSim';

interface State {
  // ── drive inputs (what makes it vibrate) ──
  rtp_amplitude: number; // RTP register 0x02 value (0..255)
  playing: number; // GO bit / sequence active
  supply_mv: number; // V_MOTOR supply (for VBAT read)
  resonance_hz: number; // actual LRA resonance (for LRA_PERIOD read)
  fault_overtemp: number;
  fault_overcurrent: number;

  // ── configuration ──
  mode: number; // 0 int-trig,1 ext-edge,2 ext-level,3 pwm/analog,4 audio,5 rtp,6 diag,7 cal
  standby: number;
  library: number; // 1..5 ERM A-E, 6 LRA
  closed_loop: number;
  rated_voltage: number;
  od_clamp: number;
  rtp_unsigned: number; // CONTROL3[3] DATA_FORMAT_RTP
  bidir: number; // CONTROL2[7] BIDIR_INPUT
  trigger_mode: number;
  last_effect: number;
  calibrated: number; // DIAG_RESULT after calibrate (1 = converged)
  diag_pass: number; // DIAG_RESULT after diagnose
  otp_programmed: number;

  [field: string]: number;
}

const DEVICE_ID = 0x60; // STATUS[7:5] = 3
const I2C_ADDR = 0x5a;

// Current drive envelope, 0..1, from mode + amplitude. Models the magnitude of
// the differential OUT+/OUT- drive (not the AC waveform itself).
function driveStrength(s: State): number {
  if (s.standby === 1) return 0;
  if (s.mode === 5) {
    // RTP: amplitude register 0x02, signed (default) or unsigned.
    if (s.rtp_unsigned === 1) return Math.min(1, s.rtp_amplitude / 255);
    const v = s.rtp_amplitude > 127 ? s.rtp_amplitude - 256 : s.rtp_amplitude; // int8
    return Math.min(1, Math.abs(v) / 127);
  }
  if (s.mode <= 2 && s.playing === 1) return 0.8; // library effect playing (nominal)
  return 0;
}

const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;

const sim: TileSim<State> = {
  tile: 'Drive.H',

  defaultState: {
    rtp_amplitude: 0,
    playing: 0,
    supply_mv: 3700,
    resonance_hz: 175, // typical LRA
    fault_overtemp: 0,
    fault_overcurrent: 0,

    mode: 0,
    standby: 0,
    library: 6, // LRA
    closed_loop: 0,
    rated_voltage: 0x1a, // 0.7 Vrms
    od_clamp: 0x25,
    rtp_unsigned: 0,
    bidir: 1,
    trigger_mode: 0,
    last_effect: 0,
    calibrated: 0,
    diag_pass: 0,
    otp_programmed: 0,
  },

  controls: [
    { type: 'slider', field: 'rtp_amplitude', label: 'RTP amplitude', min: 0, max: 127, step: 1 },
    { type: 'slider', field: 'playing', label: 'Playing (GO)', min: 0, max: 1, step: 1 },
    { type: 'slider', field: 'mode', label: 'Mode (0-int 5-RTP)', min: 0, max: 7, step: 1 },
    {
      type: 'slider',
      field: 'supply_mv',
      label: 'Supply',
      min: 2500,
      max: 5500,
      step: 50,
      unit: 'mV',
    },
    {
      type: 'slider',
      field: 'resonance_hz',
      label: 'LRA resonance',
      min: 125,
      max: 300,
      step: 1,
      unit: 'Hz',
    },
    { type: 'slider', field: 'fault_overtemp', label: 'Fault: over-temp', min: 0, max: 1, step: 1 },
    {
      type: 'slider',
      field: 'fault_overcurrent',
      label: 'Fault: over-current',
      min: 0,
      max: 1,
      step: 1,
    },
  ],

  hostCalls: {
    // ── lifecycle ──
    tile_drive_h_find: () => ({ scalar: I2C_ADDR }),
    tile_drive_h_init: () => ({ scalar: 0, nextState: { mode: 0, standby: 0, library: 6 } }),
    tile_drive_h_standby: () => ({ nextState: { standby: 1 } }),
    tile_drive_h_wake: () => ({ nextState: { standby: 0 } }),

    // ── sequence / library playback ──
    tile_drive_h_play: ({ args }) => ({
      nextState: { last_effect: pick(args, 0, 1), playing: 1, mode: 0 },
    }),
    tile_drive_h_play_sequence: () => ({ nextState: { playing: 1, mode: 0 } }),
    tile_drive_h_load_sequence: () => ({ nextState: {} }),
    tile_drive_h_set_sequence_wait: () => ({ nextState: {} }),
    tile_drive_h_set_trigger: ({ state, args }) => ({
      nextState: {
        trigger_mode: pick(args, 0, state.trigger_mode),
        mode: pick(args, 0, state.mode),
      },
    }),
    tile_drive_h_is_playing: ({ state }) => ({ scalar: state.playing }),
    tile_drive_h_stop: () => ({ nextState: { playing: 0, rtp_amplitude: 0 } }),

    // ── library + actuator tuning ──
    tile_drive_h_set_library: ({ state, args }) => ({
      nextState: { library: pick(args, 0, state.library) },
    }),
    tile_drive_h_set_actuator_params: ({ state, args }) => ({
      nextState: {
        rated_voltage: pick(args, 0, state.rated_voltage),
        od_clamp: pick(args, 1, state.od_clamp),
      },
    }),
    tile_drive_h_set_resonance_params: () => ({ nextState: {} }),
    tile_drive_h_set_waveform_timing: () => ({ nextState: {} }),

    // ── real-time playback ──
    tile_drive_h_rtp_start: () => ({ nextState: { mode: 5, rtp_amplitude: 0 } }),
    tile_drive_h_rtp_write: ({ state, args }) => ({
      nextState: { rtp_amplitude: pick(args, 0, state.rtp_amplitude) },
    }),
    tile_drive_h_set_rtp_format: ({ state, args }) => ({
      nextState: {
        rtp_unsigned: pick(args, 0, state.rtp_unsigned),
        bidir: pick(args, 1, state.bidir),
      },
    }),
    tile_drive_h_rtp_stop: () => ({ nextState: { rtp_amplitude: 0, mode: 0 } }),

    // ── PWM / analog / audio input ──
    tile_drive_h_pwm_input_start: () => ({ nextState: { mode: 3 } }),
    tile_drive_h_analog_input_start: () => ({ nextState: { mode: 3 } }),
    tile_drive_h_pwm_input_stop: () => ({ nextState: { mode: 0 } }),
    tile_drive_h_audio_start: () => ({ nextState: { mode: 4 } }),
    tile_drive_h_set_audio_params: () => ({ nextState: {} }),
    tile_drive_h_audio_stop: () => ({ nextState: { mode: 0 } }),

    // ── status / diagnostics ──
    // STATUS 0x00: DEVICE_ID[7:5]=3, OVER_TEMP[1], OC_DETECT[0].
    tile_drive_h_get_status: ({ state }) => ({
      scalar: DEVICE_ID | (state.fault_overtemp ? 0x02 : 0) | (state.fault_overcurrent ? 0x01 : 0),
    }),
    tile_drive_h_diagnose: ({ state }) => ({
      scalar: state.fault_overcurrent ? 0 : 1,
      nextState: { diag_pass: state.fault_overcurrent ? 0 : 1 },
    }),
    tile_drive_h_calibrate: ({ state }) => ({
      scalar: state.fault_overcurrent ? 0 : 1,
      nextState: { calibrated: state.fault_overcurrent ? 0 : 1 },
    }),
    tile_drive_h_is_calibrated: ({ state }) => ({ scalar: state.calibrated }),
    // VBAT (0x21): mV = raw*5600/255; valid only while driving.
    tile_drive_h_get_vbat_mv: ({ state }) => ({
      scalar: driveStrength(state) > 0 ? state.supply_mv : 0,
    }),
    // LRA_PERIOD (0x22): Hz ~= 10156/raw; valid only while driving.
    tile_drive_h_get_resonance_hz: ({ state }) => ({
      scalar: driveStrength(state) > 0 ? state.resonance_hz : 0,
    }),

    // ── OTP (one-time, destructive) ──
    tile_drive_h_get_otp_status: ({ state }) => ({ scalar: state.otp_programmed }),
    tile_drive_h_program_otp: () => ({ scalar: 0 }),

    // ── idiomatic helpers ──
    tile_drive_h_play_click: () => ({ nextState: { last_effect: 1, playing: 1, mode: 0 } }),
    tile_drive_h_play_double_tap: () => ({ nextState: { last_effect: 10, playing: 1, mode: 0 } }),
    tile_drive_h_play_alert: () => ({ nextState: { playing: 1, mode: 0 } }),
    tile_drive_h_play_buzz: () => ({ nextState: { playing: 1, mode: 5, rtp_amplitude: 127 } }),
  },

  provenance: {
    // canonical — datasheet register/bit/conversion accurate
    tile_drive_h_find: 'canonical', // I2C 0x5A
    tile_drive_h_get_status: 'canonical', // STATUS bits
    tile_drive_h_get_vbat_mv: 'canonical', // raw*5600/255
    tile_drive_h_get_resonance_hz: 'canonical', // 10156/raw
    tile_drive_h_set_trigger: 'canonical', // MODE[2:0]
    tile_drive_h_set_library: 'canonical', // LIBRARY_SEL / N_ERM_LRA
    tile_drive_h_rtp_write: 'canonical', // RTP 0x02 encoding
    tile_drive_h_set_rtp_format: 'canonical', // CONTROL2[7]/CONTROL3[3]
    tile_drive_h_is_playing: 'canonical', // GO bit
    tile_drive_h_stop: 'canonical', // GO=0
    tile_drive_h_standby: 'canonical', // STANDBY bit
    tile_drive_h_wake: 'canonical',
    tile_drive_h_play: 'canonical', // SEQ + GO
    tile_drive_h_get_otp_status: 'canonical', // CONTROL4[2]
    // hallucinated — stubbed / not really modeled
    tile_drive_h_program_otp: 'hallucinated', // destructive; always reports "already/failed"
    tile_drive_h_set_audio_params: 'hallucinated',
    tile_drive_h_set_resonance_params: 'hallucinated',
    tile_drive_h_set_waveform_timing: 'hallucinated',
    tile_drive_h_set_sequence_wait: 'hallucinated',
    power: 'inferred', // base currents are datasheet; rail split + actuator load are modeled
    // (everything else defaults to "inferred")
  },

  // Drive output envelope on the differential OUT pads (magnitude 0..1).
  padOutputs(state) {
    const s = driveStrength(state);
    return { 'OUT+': s, 'OUT-': s };
  },

  // Electrical. Two tile rails (Drive-H-a.json), matching the DRV2605's split
  // architecture: V+ VDD logic (1.8-5 V, pad 10) and V_MOTOR boost/drive supply
  // (2.5-5.5 V, pad 9). VDD draws the logic/control current (standby 1.9 µA,
  // quiescent 0.6 mA — datasheet); V_MOTOR feeds the integrated boost + H-bridge
  // (~2.9 mA average operation + the actuator load) only while driving. The
  // actuator load itself isn't datasheet-specified, so power = "inferred".
  power(state) {
    if (state.standby === 1) {
      return {
        draw_ua: 1.9,
        rails: [
          {
            name: 'V+',
            role: 'supply',
            v_mv: 3300,
            i_ua: 1.9,
            pads: ['10'],
            note: 'VDD logic — standby',
          },
          {
            name: 'V_MOTOR',
            role: 'supply',
            v_mv: state.supply_mv,
            i_ua: 0,
            pads: ['9'],
            note: 'boost/drive supply — idle',
          },
        ],
      };
    }
    const s = driveStrength(state);
    const driving = s > 0;
    const logic_ua = 600; // VDD quiescent, enabled
    const drive_ua = driving ? 2900 + s * 100000 : 0; // boost operation + actuator load (est.)
    return {
      draw_ua: logic_ua + drive_ua,
      rails: [
        { name: 'V+', role: 'supply', v_mv: 3300, i_ua: logic_ua, pads: ['10'], note: 'VDD logic' },
        {
          name: 'V_MOTOR',
          role: 'supply',
          v_mv: state.supply_mv,
          i_ua: drive_ua,
          pads: ['9'],
          note: 'boost/drive supply + actuator (load est.)',
        },
        {
          name: 'OUT±',
          role: 'output',
          v_mv: Math.round(s * 2400),
          i_ua: driving ? Math.round(s * 100000) : 0,
          pads: ['7', '8'],
          note: 'boosted actuator drive',
        },
      ],
    };
  },
};

export default sim;
